compile.workshop:
variables {
    global:
        0: arr
        1: n
        2: i
        3: code
    player:
        0: parr
        1: pn
        2: pi
}

//Optimize for size enabled
rule ("values") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Global Variable(n, Empty Array);
        Modify Global Variable(arr, Subtract, Empty Array);
        Modify Global Variable(arr, Append To Array, Empty Array);
        Modify Global Variable(arr, Remove From Array By Value, Empty Array);
        Modify Global Variable At Index(arr, False, Subtract, Empty Array);
        Modify Global Variable At Index(arr, False, Append To Array, Empty Array);
        Modify Player Variable(Event Player, parr, Append To Array, Empty Array);
        Modify Player Variable(Event Player, pn, Subtract, Empty Array);
        Modify Global Variable(n, Min, Empty Array);
        Modify Global Variable(n, Max, Empty Array);
        For Global Variable(i, 0, Empty Array, True);
        End;
        For Global Variable(i, Empty Array, 5, True);
        End;
        For Global Variable(i, 1, 5, Empty Array);
        End;
        For Player Variable(Event Player, pi, 0, Empty Array, True);
        End;
        Set Global Variable(arr, Array(Empty Array, Custom String("x")));
        If(True);
            Skip(Value In Array(Array(1, Null), Add(True, Index Of Array Value(Array(Empty Array), Global.code))));
        //__label_switch_2_0__:
        Set Global Variable(n, 1);
        //__label_switch_2_default__:
        Set Global Variable(n, 2);
        End;
    }
}

